  `c2` char(255) DEFAULT NULL,
  `c3` char(255) DEFAULT NULL,
  `c4` char(255) DEFAULT NULL,
  `c5` char(255) DEFAULT NULL,
  `c6` char(255) DEFAULT NULL,
  `c7` char(255) DEFAULT NULL,
  `c8` char(255) DEFAULT NULL,
  `c9` char(255) DEFAULT NULL,
  `c10` char(255) DEFAULT NULL,
  `c11` char(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
